:root {
  /* ===== Culori principale ===== */
  --chat--color-primary: #0f5c56;
  --chat--color-primary-shade-50: #0c4a45;
  --chat--color-primary-shade-100: #093733;

  --chat--color-secondary: #0b1f3a;
  --chat--color-secondary-shade-50: #071528;

  --chat--color-white: #ffffff;
  --chat--color-light: #f4f6fa;
  --chat--color-light-shade-50: #e5e9f0;
  --chat--color-light-shade-100: #d3d9e3;
  --chat--color-medium: #94a3b8;
  --chat--color-dark: #0b1f3a;
  --chat--color-disabled: #64748b;
  --chat--color-typing: #475569;

  /* ===== Aspect general ===== */
  --chat--spacing: 1rem;
  --chat--border-radius: 16px;
  --chat--transition-duration: 0.2s;

  --chat--font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Arial,
    sans-serif;

  /* ===== Header ===== */
  --chat--header-height: auto;
  --chat--header--padding: 1.5rem 1.75rem 1.35rem;
  --chat--header--background: linear-gradient(135deg, #0b1f3a 0%, #123156 55%, #0f5c56 130%);
  --chat--header--color: #ffffff;
  --chat--header--border-bottom: 3px solid #2dd4bf;

  --chat--heading--font-size: 1.55rem;
  --chat--subtitle--font-size: 0.9rem;
  --chat--subtitle--line-height: 1.5;

  /* ===== Corpul chatului ===== */
  --chat--body--background: #f4f6fa;
  --chat--messages-list--padding: 1.5rem;

  /* ===== Mesaje ===== */
  --chat--message--font-size: 0.95rem;
  --chat--message-line-height: 1.5;
  --chat--message--padding: 0.85rem 1.1rem;
  --chat--message--border-radius: 16px;
  --chat--message--margin-bottom: 0.7rem;

  --chat--message--bot--background: #ffffff;
  --chat--message--bot--color: #1c2333;
  --chat--message--bot--border: 1px solid #e5e9f0;

  --chat--message--user--background: linear-gradient(135deg, #0f5c56, #0c4a45);
  --chat--message--user--color: #ffffff;
  --chat--message--user--border: none;

  --chat--message--pre--background: #f4f6fa;

  /* ===== Zona de introducere ===== */
  --chat--textarea--height: 54px;
  --chat--textarea--max-height: 180px;

  --chat--input--font-size: 0.95rem;
  --chat--input--background: #ffffff;
  --chat--input--text-color: #0b1f3a;
  --chat--input--padding: 0.85rem 1rem;
  --chat--input--border: 1.5px solid #d3d9e3;
  --chat--input--border-active: 1.5px solid #2dd4bf;
  --chat--input--border-radius: 24px;

  /* ===== Butoane ===== */
  --chat--input--send--button--background: linear-gradient(135deg, #0f5c56, #2dd4bf);
  --chat--input--send--button--color: #ffffff;
  --chat--input--send--button--background-hover: #0c4a45;
  --chat--input--send--button--color-hover: #ffffff;

  --chat--input--file--button--background: #ffffff;
  --chat--input--file--button--color: #0f5c56;
  --chat--input--file--button--background-hover: #f0fdfa;
  --chat--input--file--button--color-hover: #0c4a45;

  /* ===== Footer ===== */
  --chat--footer--background: #f4f6fa;
  --chat--footer--color: #64748b;
}

/* ===== Header ===== */
.chat-header {
  min-height: auto !important;
  box-shadow: 0 6px 20px rgba(11, 31, 58, 0.22);
  position: relative;
  overflow: hidden;
}

/* accent decorativ subtil în header — element unic de brand */
.chat-header::before {
  content: "";
  position: absolute;
  top: -50px;
  right: -30px;
  width: 140px;
  height: 140px;
  background: radial-gradient(circle, rgba(45, 212, 191, 0.22) 0%, transparent 70%);
  border-radius: 50%;
  pointer-events: none;
}

.chat-heading {
  margin: 0 !important;
  font-weight: 700 !important;
  letter-spacing: -0.02em;
  position: relative;
  z-index: 1;
}

.chat-subtitle {
  margin-top: 0.4rem !important;
  opacity: 0.78;
  position: relative;
  z-index: 1;
}

/* ===== Zona de mesaje ===== */
.chat-messages-list {
  justify-content: flex-start !important;
  align-content: flex-start !important;
  padding-top: 1.5rem !important;
}

.chat-message {
  max-width: 76% !important;
  box-shadow: 0 3px 10px rgba(15, 23, 42, 0.06);
  animation: chatFadeIn 0.25s ease;
}

@keyframes chatFadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.chat-message-from-bot,
.chat-message.bot {
  border-bottom-left-radius: 4px !important;
}

.chat-message-from-user,
.chat-message.user {
  border-bottom-right-radius: 4px !important;
  box-shadow: 0 4px 12px rgba(15, 92, 86, 0.25);
}

/* ===== Zona de scriere ===== */
.chat-input {
  margin: 0.75rem 1rem 1rem !important;
  border-radius: 24px !important;
  box-shadow: 0 4px 18px rgba(15, 23, 42, 0.08);
}

.chat-input:focus-within {
  box-shadow: 0 0 0 3px rgba(45, 212, 191, 0.18), 0 4px 18px rgba(15, 23, 42, 0.08);
}

/* buton de trimitere — efect hover */
.chat-input--send-button:hover,
button[class*="send"]:hover {
  transform: scale(1.05);
  transition: transform 0.15s ease;
}

/* ===== Titlurile Markdown din răspunsuri ===== */
.chat-message h1,
.chat-message h2,
.chat-message h3,
.chat-message h4 {
  color: #0b1f3a;
  margin-top: 1rem;
  margin-bottom: 0.55rem;
}

.chat-message ul,
.chat-message ol {
  padding-left: 1.4rem;
}

.chat-message hr {
  border: 0;
  border-top: 1px solid #e5e9f0;
  margin: 1rem 0;
}

/* ===== Adaptare pentru telefoane ===== */
@media (max-width: 700px) {
  .chat-message {
    max-width: 92% !important;
  }

  .chat-header {
    padding: 1.1rem !important;
  }
}

