assignments.value:
={{
(() => {
  const raw = $json.output;

  if (typeof raw !== 'string') {
    return raw;
  }

  let data;

  try {
    data = JSON.parse(raw);
  } catch (error) {
    // Nu este JSON valid, deci presupunem că este deja Markdown/text.
    return raw;
  }

  const agenti =
    data.agenti_apelati ??
    data['agenti apelati'] ??
    data['agenți apelați'] ??
    [];

  const tipCaz =
    data.tip_cazului ??
    data['tipul cazului'] ??
    data['tip caz'] ??
    'Nespecificat';

  const scorRisc =
    data.scor_risc ??
    data['scorul de risc'] ??
    data['scor risc'] ??
    'Nespecificat';

  const dovezi = data.dovezi ?? [];

  const limitari =
    data.limitari ??
    data['limitările'] ??
    data['limite'] ??
    [];

  const recomandari =
    data.recomandari ??
    data['recomandări'] ??
    [];

  const nivelIncredere =
    data.nivel_incredere ??
    data['nivel de încredere'] ??
    data.incredere ??
    'Nespecificat';

  return `## Rezultatul analizei

**Tipul cazului:** ${tipCaz}

**Scor de risc:** ${scorRisc}/100

### Agenți apelați

${Array.isArray(agenti) && agenti.length
  ? agenti.map(agent => `- ${agent}`).join('\n')
  : '- Nespecificat'}

### Dovezi

${Array.isArray(dovezi) && dovezi.length
  ? dovezi.map(dovada => `- ${dovada}`).join('\n')
  : '- Nu au fost furnizate dovezi.'}

### Limitări

${Array.isArray(limitari) && limitari.length
  ? limitari.map(limita => `- ${limita}`).join('\n')
  : '- Nu au fost specificate limitări.'}

### Recomandări

${Array.isArray(recomandari) && recomandari.length
  ? recomandari.map(recomandare => `- ${recomandare}`).join('\n')
  : '- Nu au fost furnizate recomandări.'}

### Nivel de încredere

${nivelIncredere}
`;
})()
}}
